/**
 * 名字是否在图标表里。
 * 文件 / 记忆里来的图标 id 是字符串，渲染前必须过这道守卫——
 * 不允许 `as IconName`，那是把「图标没了」伪装成「图标画了」。
 */
export function isIconName(value: string): value is IconName {
  return Object.prototype.hasOwnProperty.call(ICONS, value);
}

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'name' | 'width' | 'height'> {
  name: IconName;
}

export function Icon({ name, className, ...rest }: IconProps) {
  const data = ICONS[name];
  if (!data) return null;
  return (
    <svg
      viewBox={data.viewBox}
      className={className ? `mm-icon ${className}` : 'mm-icon'}
      width="1em"
      height="1em"
      fill="currentColor"
      aria-hidden="true"
      {...rest}
      dangerouslySetInnerHTML={{ __html: data.inner }}
    />
  );
}
